<script>
 import { Feather, BookOpen, GitBranch, Play, Plus, ChevronRight, ArrowLeft, Settings2, Download, X, Sparkles, Check, Search, Map, Trash2, Moon, ScrollText, Castle, CircleHelp, Menu, Maximize2, Minimize2, Copy, Undo2, Upload, ChevronLeft, ArrowUpRight, Save }  from 'lucide-svelte';
 import { onMount } from 'svelte';
 let scenes = $state([
 {id:1,title:'The letter that found you',tag:'The beginning',text:'The letter arrived at precisely midnight.\n\nNot through the letterbox, nor beneath the door, but floating on a current of cold air that smelled faintly of rain and ancient stone. It settled on your windowsill, its emerald wax seal glimmering in the moonlight.\n\nYour name was written in a hand you had never seen before. And yet, somehow, you recognised it.\n\nOutside, an owl watched. Waiting.',choices:[{label:'Break the emerald seal',target:2},{label:'Follow the mysterious owl',target:3}]},
 {id:2,title:'An invitation to the impossible',tag:'Discovery',text:'The seal broke with a soft flash of green light.\n\n“Dear apprentice,” the letter began, “there are doors in this world that open only for those who have forgotten to stop believing.”\n\nBeneath the words, a map slowly drew itself in silver ink. At its centre stood a castle you had dreamed of a hundred times.',choices:[{label:'Find the hidden station',target:4},{label:'Read the silver inscription',target:5}]},
 {id:3,title:'On the wings of night',tag:'A different path',text:'You opened the window. The owl spread its wings, scattering tiny sparks across the night.\n\nAcross the rooftops, a winding stairway of starlight appeared. You took a breath, then stepped into the impossible.',choices:[{label:'Climb the starlit stairway',target:4}]},
 {id:4,title:'Beyond the iron gates',tag:'Arrival',text:'The castle rose from the mist like a memory made of stone. A thousand windows glowed with candlelight.\n\nAt the gates, a woman in midnight-blue robes smiled. “We wondered when you would arrive.”\n\nYou stepped across the threshold. Your story had only just begun.',choices:[]},
 {id:5,title:'The forgotten spell',tag:'A secret ending',text:'The silver letters rearranged themselves beneath your fingertips.\n\nYou whispered the words, and the room blossomed into a forest of stars. Somewhere in the distance, a bell rang thirteen times.\n\nYou had found the magic that had been waiting for you all along.',choices:[]}
 ]);
 let selected=$state(1), tab=$state('write'), playing=$state(false), playId=$state(1), history=$state([]), toast=$state(''), query=$state(''), saved=$state(false), title=$state('The Midnight Invitation'), modal=$state(false), mobileMenu=$state(false), focusMode=$state(false), fontSize=$state(17), saveStatus=$state('Saved'), mapFilter=$state('all'), deleted=$state(null);
 let scene=$derived(scenes.find(s=>s.id===selected) || scenes[0]);
 let playScene=$derived(scenes.find(s=>s.id===playId)||scenes[0]);
 let words=$derived(scenes.reduce((n,s)=>n+s.text.trim().split(/\s+/).filter(Boolean).length,0));
 onMount(()=>{try {let data=JSON.parse(localStorage.getItem('enchanted-quill'));if(data?.scenes?.length){scenes=data.scenes;title=data.title||title;selected=scenes[0].id;}}catch{} saved=true;});
 $effect(()=>{
  if(!saved)return;
  const data=JSON.stringify({scenes,title});
  saveStatus='Saving';
  const timer=setTimeout(()=>{try{localStorage.setItem('enchanted-quill',data);saveStatus='Saved';}catch{saveStatus='Storage full. Export a backup';}},400);
  return ()=>clearTimeout(timer);
 });
 function notify(t){toast=t;setTimeout(()=>toast='',2800);}
 function addScene(){let id=Math.max(...scenes.map(s=>s.id))+1;scenes.push({id,title:'An unwritten adventure',tag:'New scene',text:'',choices:[]});selected=id;tab='write';notify('A new page in your story.');}
 function addChoice(){scene.choices.push({label:'A new possibility',target:scenes.find(s=>s.id!==scene.id)?.id||scene.id});}
 function exportStory(){let blob=new Blob([JSON.stringify({title,scenes},null,2)],{type:'application/json'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='enchanted-story.json';a.click();URL.revokeObjectURL(a.href);notify('Your story has been exported.');}
 function removeScene(){if(scenes.length===1)return;deleted={scenes:JSON.parse(JSON.stringify(scenes)),selected,title};let id=scene.id;scenes=scenes.filter(s=>s.id!==id);scenes.forEach(s=>s.choices=s.choices.filter(c=>c.target!==id));selected=scenes[0].id;notify('Scene deleted. You can undo this.');}
 function undoDelete(){if(!deleted)return;scenes=deleted.scenes;selected=deleted.selected;title=deleted.title||title;deleted=null;notify('Scene restored.');}
 function selectScene(id){selected=Number(id);tab='write';mobileMenu=false;}
 function autoGrow(node){let frame;let width=0;const resize=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{node.style.height='auto';node.style.height=`${node.scrollHeight}px`;});};const observer=new ResizeObserver(entries=>{const next=entries[0].contentRect.width;if(next!==width){width=next;resize();}});observer.observe(node);resize();return{update(){resize();},destroy(){observer.disconnect();cancelAnimationFrame(frame);}};}
 function turnPage(id){history.push(playId);playId=id;document.querySelector('.reader')?.scrollTo({top:0,behavior:'smooth'});}
 function startReading(id=scenes[0].id){playing=true;playId=id;history=[];mobileMenu=false;}
 function duplicateScene(){let source=JSON.parse(JSON.stringify(scene));source.id=Math.max(...scenes.map(s=>s.id))+1;source.title+=' (copy)';scenes.push(source);selected=source.id;notify('Scene duplicated.');}
 function linkNewScene(){let from=scene;addScene();from.choices.push({label:'Continue the story',target:selected});notify('New scene connected.');}
 function moveScene(direction){let index=scenes.findIndex(s=>s.id===selected);selectScene(scenes[(index+direction+scenes.length)%scenes.length].id);}
 function keydown(e){if(e.key==='Escape'){playing=false;modal=false;mobileMenu=false;focusMode=false;}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();startReading(selected);}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();try{localStorage.setItem('enchanted-quill',JSON.stringify({scenes,title}));notify('Story saved to this browser.');}catch{notify('Storage is full. Export your story.');}}}
 async function importStory(e){let file=e.target.files?.[0];if(!file)return;try{let data=JSON.parse(await file.text());if(typeof data.title!=='string'||!Array.isArray(data.scenes)||!data.scenes.length)throw Error();let ids=new Set();for(let s of data.scenes){if(!Number.isSafeInteger(s.id)||ids.has(s.id)||typeof s.title!=='string'||typeof s.text!=='string'||!Array.isArray(s.choices))throw Error();ids.add(s.id);}for(let s of data.scenes)for(let c of s.choices)if(typeof c.label!=='string'||!ids.has(c.target))throw Error();deleted={scenes:JSON.parse(JSON.stringify(scenes)),selected,title};scenes=data.scenes;title=data.title;selected=scenes[0].id;tab='write';notify('Story imported.');}catch{notify('Choose a valid Enchanted Quill story JSON file.');}e.target.value='';}
 function trapFocus(node){const previous=document.activeElement;node.focus();function key(e){if(e.key!=='Tab')return;const items=[...node.querySelectorAll('button,input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled);if(!items.length)return;if(e.shiftKey&&(document.activeElement===items[0]||document.activeElement===node)){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus();}}node.addEventListener('keydown',key);return{destroy(){node.removeEventListener('keydown',key);previous?.focus();}};}
 let filteredScenes=$derived(scenes.filter(s=>mapFilter==='endings'?s.choices.length===0:mapFilter==='unlinked'?s.id!==scenes[0].id&&!scenes.some(from=>from.choices.some(c=>c.target===s.id)):true));

</script>
<svelte:head>
 <link rel="preconnect" href="https://fonts.googleapis.com"/>
 <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin="anonymous"/>
 <link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"/>
</svelte:head>
<svelte:window onkeydown={keydown}/>
<div class="app" class:focused={focusMode}>
 <img class="world-background" src="/images/castle.jpg" alt="" fetchpriority="high"/>
 {#if mobileMenu}<button class="drawer-backdrop" aria-label="Close navigation" onclick={()=>mobileMenu=false}></button>{/if}
 <aside class="sidebar" class:mobile-open={mobileMenu}>
  <a class="brand" href="/" onclick={(e)=>{e.preventDefault();tab='write';mobileMenu=false;}}><div class="brand-mark"><Feather size={25}/></div><span>Enchanted<span>Quill</span></span></a>
  <button class="drawer-close icon" aria-label="Close menu" onclick={()=>mobileMenu=false}><X size={20}/></button>
  <div class="workspace-label">WORKSPACE</div>
  <button class="nav" class:active={tab==='write'} onclick={()=>{tab='write';mobileMenu=false;}}><BookOpen size={18}/> Story editor</button>
  <button class="nav" class:active={tab==='map'} onclick={()=>{tab='map';mobileMenu=false;}}><GitBranch size={18}/> Story map <span class="nav-count">{scenes.length}</span></button>
  <button class="nav" onclick={()=>startReading()}><Play size={17}/> Play story</button>
  <div class="scenes-heading"><span>SCENES</span><button class="icon" title="Add scene" aria-label="Add scene" onclick={()=>{addScene();mobileMenu=false;}}><Plus size={17}/></button></div>
  <label class="search"><Search size={15}/><input placeholder="Find a scene" aria-label="Find a scene" bind:value={query}/>{#if query}<button class="icon" aria-label="Clear search" onclick={()=>query=''}><X size={13}/></button>{/if}</label>
  <div class="scene-list">{#each scenes.filter(s=>s.title.toLowerCase().includes(query.toLowerCase())) as s}
   <button class="scene-link" class:selected={selected===s.id} onclick={()=>selectScene(s.id)}><span class="scene-number">{String(s.id).padStart(2,'0')}</span><span>{s.title}</span>{#if selected===s.id}<span class="gold-dot"></span>{/if}</button>
  {/each}{#if !scenes.some(s=>s.title.toLowerCase().includes(query.toLowerCase()))}<p class="empty-search">No scenes found.</p>{/if}</div>
  <button class="add-scene" onclick={()=>{addScene();mobileMenu=false;}}><Plus size={17}/> New scene</button>
  <div class="sidebar-bottom"><div class="workspace-note"><span class="status-dot"></span> Your own little world<p>{scenes.length} scenes. Endless possibilities.</p></div><label class="import"><Upload size={16}/> Import a story<input type="file" accept="application/json,.json" onchange={importStory}/></label><button class="profile" onclick={()=>{modal=true;mobileMenu=false;}}><div class="avatar"><Feather size={17}/></div><div><strong>Your writing desk</strong><small>Guide & keyboard shortcuts</small></div><CircleHelp size={16}/></button></div>
 </aside>
 <main>
  <header><div class="header-left"><button class="mobile-menu icon" aria-label="Open menu" aria-expanded={mobileMenu} onclick={()=>mobileMenu=!mobileMenu}><Menu size={22}/></button><div class="breadcrumb">My stories <ChevronRight size={13}/><span>{title}</span></div></div><div class="header-actions"><span class="saved" aria-live="polite"><span class="status-dot" class:saving={saveStatus==='Saving'}></span>{saveStatus}</span><button class="export" onclick={exportStory} title="Export story"><Download size={16}/><span>Export</span></button><button class="play-button" onclick={()=>startReading()}><Play size={14} fill="currentColor"/> <span>Play story</span></button></div></header>
  <section class="hero"><div class="hero-content"><div class="eyebrow"><span class="live-spark">✦</span> A LITTLE MAGIC. A LOT OF POSSIBILITY.</div><h1>The next chapter<br/>is <span>yours.</span></h1><p>Build a world. Leave a choice.<br/>Let your reader find their own way.</p><button class="hero-action" onclick={()=>{tab='write';document.getElementById('story-workspace')?.scrollIntoView({behavior:'smooth',block:'start'});}}>Continue writing <ArrowUpRight size={17}/></button></div><div class="photo-caption"><span class="status-dot"></span> Somewhere between a dream and a story</div></section>
  <div id="story-workspace" class="story-workspace">
   <section class="story-heading"><div class="story-info"><label for="story-name" class="eyebrow">YOUR STORY</label><input id="story-name" class="story-title" aria-label="Story title" bind:value={title}/><div class="story-meta"><button onclick={()=>tab='map'}><ScrollText size={14}/>{scenes.length} scenes</button><button onclick={()=>tab='map'}><GitBranch size={14}/>{scenes.reduce((n,s)=>n+s.choices.length,0)} choices</button><span>{words} words</span><span class="draft">Draft</span></div></div><div class="view-toggle"><button class:chosen={tab==='write'} aria-pressed={tab==='write'} onclick={()=>tab='write'}><Feather size={15}/> Write</button><button class:chosen={tab==='map'} aria-pressed={tab==='map'} onclick={()=>tab='map'}><GitBranch size={15}/> Map</button></div></section>
   {#if deleted}<div class="undo-bar"><span>A previous version is available.</span><button onclick={undoDelete}><Undo2 size={14}/> Restore scenes</button><button class="icon" aria-label="Dismiss restore" onclick={()=>deleted=null}><X size={14}/></button></div>{/if}
   {#if tab==='write'}
    <div class="editor-navigation"><div class="scene-switcher"><button class="icon" aria-label="Previous scene" onclick={()=>moveScene(-1)}><ChevronLeft size={18}/></button><select aria-label="Current scene" value={selected} onchange={(e)=>selectScene(e.currentTarget.value)}>{#each scenes as s}<option value={s.id}>Scene {String(s.id).padStart(2,'0')} · {s.title}</option>{/each}</select><button class="icon" aria-label="Next scene" onclick={()=>moveScene(1)}><ChevronRight size={18}/></button></div><button class="new-scene-button" aria-label="New scene" onclick={addScene}><Plus size={16}/><span>New scene</span></button></div>
    <div class="editor-layout"><section class="paper"><div class="paper-toolbar"><div class="scene-indicator"><span class="status-dot"></span> SCENE {String(scene.id).padStart(2,'0')}</div><div class="editor-tools"><button class="icon" aria-label="Smaller writing text" disabled={fontSize<=14} onclick={()=>fontSize=Math.max(14,fontSize-1)}>A<span class="small-minus">−</span></button><span class="font-size">{fontSize}</span><button class="icon" aria-label="Larger writing text" disabled={fontSize>=24} onclick={()=>fontSize=Math.min(24,fontSize+1)}>A<Plus size={9}/></button><button title="Duplicate scene" class="icon" aria-label="Duplicate scene" onclick={duplicateScene}><Copy size={15}/></button><button title="Delete scene" class="icon delete" aria-label="Delete scene" disabled={scenes.length===1} onclick={removeScene}><Trash2 size={15}/></button><button title={focusMode?'Exit focus mode':'Focus mode'} class="icon" aria-label={focusMode?'Exit focus mode':'Focus mode'} aria-pressed={focusMode} onclick={()=>focusMode=!focusMode}>{#if focusMode}<Minimize2 size={16}/>{:else}<Maximize2 size={16}/>{/if}</button></div></div><input class="scene-title" aria-label="Scene title" placeholder="Name this scene" bind:value={scene.title}/><textarea class="story-text" style:font-size={`${fontSize}px`} use:autoGrow={{text:scene.text,size:fontSize}} aria-label="Scene content" placeholder="Start with a place, a person, or something that should not have happened..." bind:value={scene.text}></textarea><div class="paper-footer"><span>{scene.text.trim().split(/\s+/).filter(Boolean).length} words <span class="reading-time">{Math.max(1,Math.ceil(scene.text.trim().split(/\s+/).filter(Boolean).length/200))} min read</span></span><button onclick={()=>startReading(selected)}><Play size={13}/> Preview scene</button></div></section>
     <aside class="choices-panel"><div class="choices-title"><div class="branch-icon"><GitBranch size={20}/></div><div><h2>What happens next?</h2><p>The reader gets to choose.</p></div></div><div class="choice-list">{#each scene.choices as choice,i}<div class="choice-card"><div class="choice-label"><span>OPTION {String(i+1).padStart(2,'0')}</span><button title="Remove choice" aria-label={`Remove choice ${i+1}`} class="icon" onclick={()=>scene.choices.splice(i,1)}><X size={14}/></button></div><input aria-label={`Choice ${i+1} text`} placeholder="What can the reader do?" bind:value={choice.label}/><label class="leads"><span>Go to</span><select aria-label={`Choice ${i+1} destination`} bind:value={choice.target}>{#each scenes as target}<option value={target.id}>{String(target.id).padStart(2,'0')} · {target.title}</option>{/each}</select><button class="icon" aria-label={`Open choice ${i+1} destination`} onclick={()=>selectScene(choice.target)}><ArrowUpRight size={16}/></button></label></div>{/each}{#if !scene.choices.length}<div class="empty-choices"><BookOpen size={25}/><h3>An ending, or a beginning?</h3><p>Leave this as an ending or add a path to keep the story going.</p></div>{/if}</div><button class="add-choice" onclick={addChoice}><Plus size={16}/> Add a choice</button><button class="connect-scene" onclick={linkNewScene}><GitBranch size={15}/> Create & connect a new scene <ArrowUpRight size={14}/></button><div class="tip"><span>WRITER'S NOTE</span><p>A good choice makes the reader pause. Give them something to lose, or something to discover.</p></div><button class="preview-scene" onclick={()=>startReading(selected)}><Play size={14}/> Try this path <span>Ctrl ↵</span></button></aside>
    </div>
   {:else}
    <section class="map-panel"><div class="map-intro"><div><h2>Your story, connected.</h2><p>Follow a path or open a scene to keep writing.</p></div><select aria-label="Filter story map" bind:value={mapFilter}><option value="all">All scenes</option><option value="endings">Endings</option><option value="unlinked">Unlinked scenes</option></select></div><div class="map-nodes">{#each filteredScenes as s}<div class="map-node" class:current={s.id===selected}><button class="map-scene" onclick={()=>selectScene(s.id)}><span>SCENE {String(s.id).padStart(2,'0')} {s.id===scenes[0].id?' · START':''}</span><h3>{s.title||'Untitled scene'}</h3><p>{s.text.slice(0,110)}{s.text.length>110?'…':''}</p><span class="open-scene">Open scene <ArrowUpRight size={15}/></span></button>{#each s.choices as c}<div class="connection"><GitBranch size={14}/><span>{c.label}</span><button onclick={()=>selectScene(c.target)}>Scene {c.target}<ArrowUpRight size={13}/></button></div>{/each}{#if !s.choices.length}<div class="end-label"><span class="status-dot"></span> Story ending</div>{/if}</div>{/each}{#if !filteredScenes.length}<div class="empty-map">No {mapFilter==='unlinked'?'unlinked scenes':'endings'} yet.</div>{/if}<button class="new-node" onclick={addScene}><Plus size={24}/><span>Add a scene</span></button></div></section>
   {/if}
   <footer><span>Enchanted Quill</span><span>One choice can change everything.</span><button onclick={()=>modal=true}><CircleHelp size={15}/> How it works</button></footer>
  </div>
 </main>
</div>
{#if toast}<div class="toast" role="status"><Check size={17}/>{toast}</div>{/if}
{#if playing}<div class="modal-backdrop"><div class="reader" role="dialog" aria-modal="true" aria-label="Story preview" tabindex="-1" use:trapFocus><div class="reader-header"><span><BookOpen size={17}/>{title}</span><button class="icon" aria-label="Close preview" onclick={()=>playing=false}><X size={21}/></button></div><div class="reader-body"><div class="reader-scene-label">SCENE {String(playScene.id).padStart(2,'0')}<span>{history.length+1} {history.length===0?'page':'pages'} explored</span></div><h2>{playScene.title}</h2><div class="reader-text">{playScene.text||'This scene is waiting for its first words.'}</div><div class="reader-choices">{#each playScene.choices as c,i}<button onclick={()=>turnPage(c.target)}><span class="choice-key">{i+1}</span><span>{c.label}</span><ChevronRight size={18}/></button>{/each}{#if !playScene.choices.length}<p class="the-end">You made it to the end.</p><button onclick={()=>{playId=scenes[0].id;history=[];}}><BookOpen size={17}/><span>Read another path</span><ChevronRight size={18}/></button>{/if}</div><div class="reader-footer">{#if history.length}<button class="back" onclick={()=>playId=history.pop()}><ArrowLeft size={14}/> Previous page</button>{/if}<button class="back" onclick={()=>{selected=playId;tab='write';playing=false;}}>Edit this scene <Feather size={14}/></button></div></div></div></div>{/if}
{#if modal}<div class="modal-backdrop"><div class="reader help" role="dialog" aria-modal="true" aria-label="Editor guide" tabindex="-1" use:trapFocus><div class="reader-header"><span><Feather size={18}/> Your writing desk</span><button class="icon" aria-label="Close guide" onclick={()=>modal=false}><X size={21}/></button></div><div class="reader-body"><h2>Make a story worth exploring.</h2><div class="guide-step"><span>1</span><div><h3>Write a scene</h3><p>Choose a scene from the menu or add a new one. Give it a name and start writing.</p></div></div><div class="guide-step"><span>2</span><div><h3>Give the reader a choice</h3><p>Add options and select where each one leads. You can create a new scene and connect it in one click.</p></div></div><div class="guide-step"><span>3</span><div><h3>Follow your own paths</h3><p>Open the map to see your connections. Press Play to read the story and test every choice.</p></div></div><div class="shortcuts"><span>Save story <kbd>Ctrl S</kbd></span><span>Preview scene <kbd>Ctrl Enter</kbd></span><span>Close / exit focus <kbd>Esc</kbd></span></div><p class="storage-note">Saved on this device. Export a copy to keep a backup, or import an earlier story.</p><button class="play-button" onclick={()=>modal=false}>Back to the story <ArrowUpRight size={16}/></button></div></div></div>{/if}

